package org.bytefred.ktoy.core

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

/**
 * Verifies ktoy's MINIMAL C compiler (compileSourceMini) against the Python
 * reference (pytoy minicc). For every embedded minicc example (see
 * MiniCExamples.kt, generated by scripts/gen_minicc_examples.py — only the
 * examples minicc ACCEPTS are embedded):
 *
 *   1. compileSourceMini(cSource, name) must equal pytoy minicc's golden .toys
 *      byte-for-byte.
 *   2. The compiled program, assembled and run to STOP, must leave ACC equal to
 *      the `// expect: N` value declared in the C source.
 *
 * Plus: recursion is rejected (MiniError), matching pytoy, and a handful of
 * focused unit tests for the core language.
 */
class MiniCompilerTest {

    private val safetyCap = 2_000_000
    private val expect = Regex("""//\s*expect:\s*(\d+)""", RegexOption.IGNORE_CASE)

    /** Run a machine to completion (or the safety cap). */
    private fun runToStop(machine: Machine, name: String) {
        var iterations = 0
        while (machine.step()) {
            iterations += 1
            assertTrue(iterations < safetyCap, "'$name' did not stop within $safetyCap iterations")
        }
    }

    /** Full pipeline helper: compile with minicc, assemble, run, return ACC. */
    private fun run(src: String, name: String = "t.toyc"): Int {
        val asm = compileSourceMini(src, name)
        val result = assemble(asm)
        assertTrue(result.errors.isEmpty(), "assembler errors: ${result.errors.joinToString("\n")}\n$asm")
        val machine = Machine(result.mem, result.dataAddrs)
        runToStop(machine, name)
        return machine.acc
    }

    private fun wrap(body: String): String = "int main(void) {\n$body\n}\n"

    // ── byte-identity to pytoy minicc ────────────────────────────────────────

    @Test
    fun ktoyMiniccMatchesPytoyByteForByte() {
        for (ex in MINICC_EXAMPLES) {
            val got = compileSourceMini(ex.cSource, ex.name)
            assertEquals(
                ex.expectedToys, got,
                "'${ex.name}': ktoy compileSourceMini output diverges from pytoy minicc golden",
            )
        }
    }

    @Test
    fun compiledProgramsYieldExpectedAcc() {
        for (ex in MINICC_EXAMPLES) {
            val match = assertNotNull(
                expect.find(ex.cSource),
                "'${ex.name}': no '// expect: N' marker in C source",
            )
            val expectedAcc = match.groupValues[1].toInt()
            val acc = run(ex.cSource, ex.name)
            assertEquals(expectedAcc, acc, "'${ex.name}': final ACC mismatch vs '// expect:'")
        }
    }

    // ── recursion rejected (minicc is stackfree) ─────────────────────────────

    @Test
    fun rejectsDirectRecursion() {
        val src = "int f(int n) { if (n == 0) { return 0; } return f(n - 1); }\n" +
            "int main(void) { return f(3); }\n"
        val e = assertFailsWith<MiniError> { compileSourceMini(src, "t") }
        assertTrue("recursion" in e.message!! || "stackfree" in e.message!!, e.message!!)
    }

    @Test
    fun rejectsMutualRecursion() {
        val src = "int f(int n) { return g(n); }\n" +
            "int g(int n) { return f(n); }\n" +
            "int main(void) { return f(1); }\n"
        assertFailsWith<MiniError> { compileSourceMini(src, "t") }
    }

    @Test
    fun diamondCallGraphIsNotRecursion() {
        // main->f, main->g, f->h, g->h is a DAG (shared callee), not a cycle.
        val src = "int h(int x) { return x + 1; }\n" +
            "int f(int x) { return h(x); }\n" +
            "int g(int x) { return h(x); }\n" +
            "int main(void) { return f(10) + g(20); }\n"   // 11 + 21 = 32
        assertEquals(32, run(src))
    }

    // ── focused unit tests (compile + assemble + run) ────────────────────────

    @Test
    fun arithmetic() {
        assertEquals(5, run(wrap("return 2 + 3;")))
        assertEquals(7, run(wrap("int a=10; int b=3; return a - b;")))
        assertEquals(44, run(wrap("return 200 + 100;")))       // wraps mod 256
        assertEquals(42, run(wrap("int x=6; int y=7; return x * y;")))
    }

    @Test
    fun bitwiseAndShift() {
        assertEquals(8, run(wrap("return 12 & 10;")))
        assertEquals(240, run(wrap("int x=15; return ~x;")))
        assertEquals(12, run(wrap("int x=3; return x << 2;")))
        assertEquals(25, run(wrap("int x=200; return x >> 3;")))
    }

    @Test
    fun ifElseAndWhile() {
        val ifSrc = wrap(
            "int a=7; int b=12; int r;" +
                " if (a < b) { r = b - a; } else { r = a - b; } return r;",
        )
        assertEquals(5, run(ifSrc))
        val whileSrc = wrap("int i=0; int s=0; while (i < 5) { s = s + i; i = i + 1; } return s;")
        assertEquals(10, run(whileSrc))                         // 0+1+2+3+4
    }

    @Test
    fun arraysReadAndWrite() {
        assertEquals(30, run(wrap("int a[4] = {10, 20, 30, 40}; int i=2; return a[i];")))
        val src = wrap("int a[3]; a[0]=5; a[1]=9; a[2]=1; int i=1; a[i] = a[i] + 100; return a[1];")
        assertEquals(109, run(src))
    }

    @Test
    fun nonRecursiveFunctions() {
        assertEquals(42, run("int add(int a, int b) { return a + b; }\nint main(void) { return add(20, 22); }\n"))
        assertEquals(
            25,
            run("int square(int x) { return x * x; }\nint main(void) { return square(3) + square(4); }\n"),
        )
        // sub(y, sub(a, b)): the 2nd argument re-enters sub; it must not clobber
        // the first argument's parameter slot before the outer jump.
        assertEquals(
            13,
            run("int sub(int a, int b) { return a - b; }\nint main(void) { return sub(20, sub(10, 3)); }\n"),
        )
    }

    @Test
    fun integerLiteralEdgeCasesMatchPytoy() {
        // pytoy does int(text, 0) & 0xFF with bignums: arbitrarily long literals
        // mask to their low byte (no overflow, no crash).
        assertEquals(255, run(wrap("return 99999999999999999999999999;")))   // large decimal masks
        assertEquals(255, run(wrap("return 0xFFFFFFFFFFFFFFFFFF;")))         // large hex masks
        // normal literals unchanged
        assertEquals(255, run(wrap("return 0xFF;")))
        assertEquals(255, run(wrap("return 255;")))
        // base-0 rejects a leading-zero decimal (int("010", 0) raises ValueError)
        assertFailsWith<MiniError> { compileSourceMini(wrap("return 010;"), "t") }
        // bare 0x has no hex digits
        assertFailsWith<MiniError> { compileSourceMini(wrap("return 0x;"), "t") }
    }

    // ── deliberate limits (documented, not bugs) ─────────────────────────────

    @Test
    fun rejectsVariableShift() {
        assertFailsWith<MiniError> { compileSourceMini(wrap("int x=4; int n=2; return x >> n;"), "t") }
    }

    @Test
    fun rejectsUnknownVariable() {
        assertFailsWith<MiniError> { compileSourceMini(wrap("return y;"), "t") }
    }

    @Test
    fun rejectsCompoundAssignment() {
        val e = assertFailsWith<MiniError> { compileSourceMini(wrap("int x=5; x += 3; return x;"), "t") }
        assertTrue("compound assignment" in e.message!!, e.message!!)
    }

    @Test
    fun rejectsUndefinedCall() {
        assertFailsWith<MiniError> { compileSourceMini("int main(void) { return nope(1); }", "t") }
    }

    @Test
    fun rejectsWrongArgCount() {
        val src = "int f(int a, int b) { return a + b; }\nint main(void) { return f(1); }\n"
        assertFailsWith<MiniError> { compileSourceMini(src, "t") }
    }

    @Test
    fun rejectsMissingMain() {
        assertFailsWith<MiniError> { compileSourceMini("int f(void) { return 1; }", "t") }
    }

    @Test
    fun rejectsMainWithParameters() {
        assertFailsWith<MiniError> { compileSourceMini("int main(int x) { return x; }", "t") }
    }
}
